        <!-- STAGE 2 -->\n        <div class=\"stage\" id=\"stage2\">\n          <div class=\"ring\">\n            <svg class=\"ring__svg\" viewBox=\"0 0 120 120\" aria-hidden=\"true\">\n              <defs>\n                <linearGradient id=\"rg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n                  <stop offset=\"0\" stop-color=\"#ffdf9e\"/>\n                  <stop offset=\"1\" stop-color=\"#6f5bff\"/>\n                </linearGradient>\n              </defs>\n              <circle class=\"ring__track\" cx=\"60\" cy=\"60\" r=\"52\"/>\n              <circle class=\"ring__prog\" id=\"ringProg\" cx=\"60\" cy=\"60\" r=\"52\" stroke=\"url(#rg)\"/>\n            </svg>\n            <div class=\"ring__num\" id=\"ringNum\" aria-live=\"polite\">15<small>sec</small></div>\n          </div>\n          <h3>Verifying membership</h3>\n          <p>Keep this tab open. The vault releases automatically when the countdown ends.</p>\n          <ul class=\"log\" id=\"log\" aria-live=\"polite\"></ul>\n          <p class=\"hint\">Step 2 of 3 · do not refresh</p>\n        </div>\n\n        <!-- STAGE 3 -->\n        <div class=\"stage\" id=\"stage3\">\n          <div class=\"unlocked\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <rect x=\"4\" y=\"10.5\" width=\"16\" height=\"10.5\" rx=\"2.6\"/>\n              <path d=\"M8 10.5V7.5a4 4 0 0 1 7.4-2\"/>\n              <path d=\"M9.2 15.8l2 2 3.6-3.9\"/>\n            </svg>\n          </div>\n          <h3>Vault open</h3>\n          <p>Access granted. Everything inside is free — take what you need, drop a thanks in the group.</p>\n          <a class=\"btn btn--gold btn--big\" id=\"unlockBtn\" href=\"#\" aria-disabled=\"true\" target=\"_blank\" rel=\"noopener\">\n            <span id=\"unlockTxt\">Checking…</span>\n            <span class=\"btn__ico\" aria-hidden=\"true\">↗</span>\n          </a>